// Окно 10-19.09.2026 целиком внутри одного месяца, поэтому помесячная нарезка
// (как в LED-CEK воркфлоу) тут не нужна — просто два направления.
const MONTH = '2026-09';
return [
  { json: { origin: 'LED', destination: 'REN', month: MONTH } },
  { json: { origin: 'LED', destination: 'OSW', month: MONTH } },
];

// Сводим три источника в один плоский список предложений.
// Победы тут нет намеренно: она не летает ни в Оренбург, ни в Орск.
// Аэрофлот напрямую недоступен — его цены приходят через tutu и Aviasales.
const SUF = ''; // '' для крона, ' Cmd' для ветки команды
const WINDOW = { min: '2026-09-10', max: '2026-09-19' };
const ROUTES = {
  REN: { label: 'СПб → Оренбург', node: 'Tutu LED-REN' },
  OSW: { label: 'СПб → Орск',     node: 'Tutu LED-OSW' },
};

const AIRLINES = { DP:'Победа', '5N':'Смартавиа', U6:'Уральские', FV:'Россия', SU:'Аэрофлот',
  S7:'S7', N4:'Nordwind', WZ:'Red Wings', A4:'Азимут', YC:'Ямал', UT:'ЮТэйр',
  DN:'Nordwind', ZF:'Азур', EO:'Икар', RL:'Роял Флайт', UK:'ЮВТ-Аэро' };

const parseRub = s => {
  if (!s) return null;
  const digits = String(s).replace(/[^0-9]/g, '');
  return digits ? Number(digits) : null;
};
const ruToIso = s => {
  const m = String(s || '').match(/^(\d{2})\.(\d{2})\.(\d{4})$/);
  return m ? `${m[3]}-${m[2]}-${m[1]}` : null;
};
const inRange = d => Boolean(d && d >= WINDOW.min && d <= WINDOW.max);

const results = [];

// 1. tutu — минимальная цена на каждую дату по всем перевозчикам (включая Аэрофлот/Россию)
for (const [dest, r] of Object.entries(ROUTES)) {
  try {
    const data = $(r.node + SUF).first().json || {};
    for (const [dru, v] of Object.entries(data)) {
      const date = ruToIso(dru);
      if (!inRange(date)) continue;
      const price = Number(v && v.price);
      if (!Number.isFinite(price) || price <= 0) continue;
      results.push({ to: dest, airline: 'мин. цена tutu', date, price,
                     direct: null, src: 'tutu', month_best: Boolean(v && v.is_best) });
    }
  } catch (e) {}
}

// 2. Смартавиа — прямой рейс LED→REN. В Орск не летает, ноды для OSW нет.
try {
  const data = ($('Smartavia LED-REN' + SUF).first().json.data || {})['LED-REN'] || {};
  for (const [date, v] of Object.entries(data)) {
    if (!inRange(date)) continue;
    const price = parseRub(v && v.label && v.label.value);
    if (price) results.push({ to: 'REN', airline: 'Смартавиа', date, price,
                              direct: true, src: 'smartavia' });
  }
} catch (e) {}

// 3. Travelpayouts — единственный источник, который называет перевозчика
try {
  for (const item of $('Travelpayouts' + SUF).all()) {
    const r = item.json || {};
    if (r.success === false) continue;
    const rows = Array.isArray(r.data) ? r.data : (Array.isArray(r) ? r : []);
    for (const t of rows) {
      const date = String(t.departure_at || t.depart_date || '').slice(0, 10);
      if (!inRange(date)) continue;
      if (t.origin !== 'LED') continue;
      const to = t.destination;
      if (!ROUTES[to]) continue;
      const price = Number(t.price != null ? t.price : t.value);
      if (!Number.isFinite(price) || price <= 0) continue;
      const stops = Number(t.transfers != null ? t.transfers : t.number_of_changes);
      results.push({ to, airline: AIRLINES[t.airline] || t.airline || 'н/д', date, price,
                     direct: Number.isFinite(stops) ? stops === 0 : null, src: 'aviasales' });
    }
  }
} catch (e) {}

const cheapest = list => list.slice().sort((a, b) => a.price - b.price)[0] || null;

const routes = {};
for (const [dest, r] of Object.entries(ROUTES)) {
  const rows = results.filter(x => x.to === dest);

  // минимум отдельно по каждому источнику — чтобы глазами ловить расхождение в свежести
  const bySource = {};
  for (const src of ['smartavia', 'tutu', 'aviasales']) {
    const m = cheapest(rows.filter(x => x.src === src));
    if (m) bySource[src] = m;
  }

  const byDate = {};
  for (const x of rows) {
    if (!byDate[x.date] || x.price < byDate[x.date].price) byDate[x.date] = x;
  }

  routes[dest] = {
    label: r.label,
    best: cheapest(rows),
    bySource,
    byDate: Object.values(byDate).sort((a, b) => (a.date < b.date ? -1 : 1)),
    count: rows.length,
  };
}

return [{ json: { window: WINDOW, routes } }];

// ===================== НАСТРОЙКИ =====================
const ROUTES = {
  REN: { label: 'СПб → Оренбург', threshold: 8000 },   // 🔥 жёсткий порог
  OSW: { label: 'СПб → Орск',     threshold: 13000 },
};
const DROP_PCT = 10;            // 📉 мягкий алерт: падение от прошлого минимума, %
const CHAT_ID = '648226895';
// =====================================================
// Last-minute ветки («вылет сегодня») тут нет намеренно: окно вылета фиксированное
// и на месяц вперёд, такой алерт был бы чистым шумом.

const agg = $('Aggregate').first().json;
const store = $getWorkflowStaticData('global'); // переживает запуски, без внешней БД

const NOTE = {
  smartavia: '\n⚠️ Цена из календаря Смартавиа, ориентировочная.',
  tutu: '\n⚠️ Цена из календаря tutu, на сайте перевозчика может отличаться.',
  aviasales: '\n⚠️ Цена из кэша Aviasales — проверь на сайте перевозчика.',
};
const SRC_LABEL = { smartavia: 'Смартавиа', tutu: 'tutu', aviasales: 'Aviasales' };
const MONTHS = ['янв', 'фев', 'мар', 'апр', 'мая', 'июн',
                'июл', 'авг', 'сен', 'окт', 'ноя', 'дек'];

const dm = iso => {
  const p = String(iso).split('-');
  return p.length === 3 ? `${Number(p[2])} ${MONTHS[Number(p[1]) - 1]}` : iso;
};
const rub = n => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + ' ₽';
const describe = m => `${rub(m.price)} · ${dm(m.date)} · ${m.airline}` +
  (m.direct === true ? ', прямой' : m.direct === false ? ', с пересадкой' : '');

const out = [];

for (const [dest, cfg] of Object.entries(ROUTES)) {
  const r = (agg.routes || {})[dest];
  if (!r || !r.best) continue;

  const price = r.best.price;
  const last = (store[dest] == null) ? null : Number(store[dest]);
  const was = (last == null) ? '' : ` (было ${rub(last)})`;

  let head = null;
  if (price <= cfg.threshold && (last == null || price < last)) {
    head = `🔥 ${cfg.label}`;
  } else if (last != null && price <= last * (1 - DROP_PCT / 100)) {
    head = `📉 ${cfg.label}: цена упала`;
  }
  store[dest] = price;
  if (!head) continue;

  let text = `${head}\n${describe(r.best)}${was}`;

  // остальные источники — чтобы сразу видеть, кто отстаёт по свежести
  for (const [src, m] of Object.entries(r.bySource || {})) {
    if (src === r.best.src) continue;
    text += `\n  ${SRC_LABEL[src]}: ${rub(m.price)} · ${dm(m.date)} · ${m.airline}`;
  }

  text += NOTE[r.best.src] || '';
  if (head.startsWith('🔥')) text += '\nБери, пока не разобрали!';

  out.push({ json: { chat_id: CHAT_ID, text } });
}

return out; // 0..2 сообщения -> прямо в Telegram

const QUIET_MS = 30 * 60 * 1000;
const e = $json.execution || {};
const err = e.error || {};
const wf = $json.workflow || {};
const node = e.lastNodeExecuted || '?';
const s = $getWorkflowStaticData('global');
if (!s.errAlerts) s.errAlerts = {};
const st = s.errAlerts[node] || { last: 0, suppressed: 0 };
const now = Date.now();
if (now - st.last < QUIET_MS) { st.suppressed += 1; s.errAlerts[node] = st; return []; }
const repeats = st.suppressed;
s.errAlerts[node] = { last: now, suppressed: 0 };
const text =
  `⚠️ FlightWatch REN упал\nВоркфлоу: ${wf.name || '?'}\nНода: ${node}\n` +
  `Ошибка: ${err.message || 'без текста'}` +
  (repeats ? `\n(за последние 30 мин ещё ${repeats} таких, они скрыты)` : '') +
  (e.url ? `\n${e.url}` : '');
return [{ json: { chat_id: '648226895', text } }];

