// Ответ на /prices: обе цели, разбивка по источникам и цена на каждую дату окна.
const a = $('Aggregate Cmd').first().json;
const chat_id = $('On Command').first().json.message.chat.id;

const SRC_LABEL = { smartavia: 'Смартавиа', tutu: 'tutu', aviasales: 'Aviasales' };
const MONTHS = ['янв', 'фев', 'мар', 'апр', 'мая', 'июн',
                'июл', 'авг', 'сен', 'окт', 'ноя', 'дек'];

const dm = iso => {
  const p = String(iso).split('-');
  return p.length === 3 ? `${Number(p[2])} ${MONTHS[Number(p[1]) - 1]}` : iso;
};
const rub = n => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + ' ₽';
const marks = m => (m.direct === true ? ', прямой' : m.direct === false ? ', с пересадкой' : '');
const fmt = m => m ? `${rub(m.price)} · ${dm(m.date)} · ${m.airline}${marks(m)}` : 'нет мест';

function block(r) {
  if (!r) return '';
  let s = `${r.label}\nДешевле всего: ${fmt(r.best)}\n`;
  for (const [src, m] of Object.entries(r.bySource || {})) {
    // перевозчика показываем только у Aviasales — у остальных он и так в названии источника
    const who = src === 'aviasales' ? ` · ${m.airline}` : '';
    s += `  ${SRC_LABEL[src] || src}: ${rub(m.price)} · ${dm(m.date)}${who}${marks(m)}\n`;
  }
  if ((r.byDate || []).length) {
    s += '  По датам:\n';
    for (const m of r.byDate) s += `   ${dm(m.date)} — ${rub(m.price)}\n`;
  }
  return s;
}

const w = a.window || {};
const text =
  `✈️ Вылет из СПб, ${dm(w.min)} – ${dm(w.max)}\n\n` +
  block((a.routes || {}).REN) + `\n` +
  block((a.routes || {}).OSW) +
  `\nДаты, которых нет в списке, — рейсов не нашлось.\n` +
  `Цены ориентировочные: календари перевозчика и агрегаторов, на сайте может отличаться.`;

return [{ json: { chat_id, text } }];
